// Status codes returned by this interface. MS-RPRN methods return a Win32 error code as
// their result ([MS-RPRN] 2.2.5, [MS-ERREF] 2.2), not an NTSTATUS. Only the codes commonly
// returned by the print protocol are enumerated here; StatusString falls back to the hex
// value for anything else.
const (
	StatusSuccess              uint32 = 0x00000000 // ERROR_SUCCESS
	ErrorFileNotFound          uint32 = 0x00000002 // ERROR_FILE_NOT_FOUND
	ErrorAccessDenied          uint32 = 0x00000005 // ERROR_ACCESS_DENIED
	ErrorInvalidHandle         uint32 = 0x00000006 // ERROR_INVALID_HANDLE
	ErrorNotSupported          uint32 = 0x00000032 // ERROR_NOT_SUPPORTED
	ErrorInvalidParameter      uint32 = 0x00000057 // ERROR_INVALID_PARAMETER
	ErrorInsufficientBuffer    uint32 = 0x0000007A // ERROR_INSUFFICIENT_BUFFER
	ErrorInvalidLevel          uint32 = 0x0000007C // ERROR_INVALID_LEVEL
	ErrorInvalidName           uint32 = 0x0000007B // ERROR_INVALID_NAME
	ErrorMoreData              uint32 = 0x000000EA // ERROR_MORE_DATA
	ErrorNoMoreItems           uint32 = 0x00000103 // ERROR_NO_MORE_ITEMS
	ErrorUnknownPort           uint32 = 0x00000704 // ERROR_UNKNOWN_PORT (1796)
	ErrorUnknownPrinterDriver  uint32 = 0x00000705 // ERROR_UNKNOWN_PRINTER_DRIVER (1797)
	ErrorUnknownPrintProcessor uint32 = 0x00000706 // ERROR_UNKNOWN_PRINTPROCESSOR (1798)
	ErrorInvalidPrinterName    uint32 = 0x00000709 // ERROR_INVALID_PRINTER_NAME (1801)
	ErrorPrinterAlreadyExists  uint32 = 0x0000070A // ERROR_PRINTER_ALREADY_EXISTS (1802)
	ErrorInvalidDatatype       uint32 = 0x0000070C // ERROR_INVALID_DATATYPE (1804)
	ErrorPrinterDeleted        uint32 = 0x00000771 // ERROR_PRINTER_DELETED (1905)
	ErrorInvalidPrinterState   uint32 = 0x00000772 // ERROR_INVALID_PRINTER_STATE (1906)
	ErrorPrinterDriverInUse    uint32 = 0x00000BB9 // ERROR_PRINTER_DRIVER_IN_USE (3001)
	ErrorSplNoStartdoc         uint32 = 0x00000E15 // ERROR_SPL_NO_STARTDOC (3605)
)

// SyntaxID returns the winspool abstract syntax identifier:
// 12345678-1234-abcd-ef00-0123456789ab, version 1.0.
func SyntaxID() syntax.SyntaxID {
	return syntax.SyntaxID{
		UUID:         guid.GUID{A: 0x12345678, B: 0x1234, C: 0xabcd, D: 0xef00, E: 0x0123456789ab},
		MajorVersion: 1,
		MinorVersion: 0,
	}
}

// StatusString returns a mnemonic for the documented status codes, otherwise the
// hex value.
func StatusString(status uint32) string {
	switch status {
	case StatusSuccess:
		return "ERROR_SUCCESS"
	case ErrorFileNotFound:
		return "ERROR_FILE_NOT_FOUND"
	case ErrorAccessDenied:
		return "ERROR_ACCESS_DENIED"
	case ErrorInvalidHandle:
		return "ERROR_INVALID_HANDLE"
	case ErrorNotSupported:
		return "ERROR_NOT_SUPPORTED"
	case ErrorInvalidParameter:
		return "ERROR_INVALID_PARAMETER"
	case ErrorInsufficientBuffer:
		return "ERROR_INSUFFICIENT_BUFFER"
	case ErrorInvalidName:
		return "ERROR_INVALID_NAME"
	case ErrorInvalidLevel:
		return "ERROR_INVALID_LEVEL"
	case ErrorMoreData:
		return "ERROR_MORE_DATA"
	case ErrorNoMoreItems:
		return "ERROR_NO_MORE_ITEMS"
	case ErrorUnknownPort:
		return "ERROR_UNKNOWN_PORT"
	case ErrorUnknownPrinterDriver:
		return "ERROR_UNKNOWN_PRINTER_DRIVER"
	case ErrorUnknownPrintProcessor:
		return "ERROR_UNKNOWN_PRINTPROCESSOR"
	case ErrorInvalidPrinterName:
		return "ERROR_INVALID_PRINTER_NAME"
	case ErrorPrinterAlreadyExists:
		return "ERROR_PRINTER_ALREADY_EXISTS"
	case ErrorInvalidDatatype:
		return "ERROR_INVALID_DATATYPE"
	case ErrorPrinterDeleted:
		return "ERROR_PRINTER_DELETED"
	case ErrorInvalidPrinterState:
		return "ERROR_INVALID_PRINTER_STATE"
	case ErrorPrinterDriverInUse:
		return "ERROR_PRINTER_DRIVER_IN_USE"
	case ErrorSplNoStartdoc:
		return "ERROR_SPL_NO_STARTDOC"
	default:
		return fmt.Sprintf("0x%08x", status)
	}
}

